# Prints the Socket constants table the prelude embeds: every Integer
# constant of Socket::Constants, as "NAME=value" separated by spaces, in the
# order the running ruby lists them.
#
# The values are the PLATFORM's (AF_INET6 is 30 on darwin and 10 on linux,
# SOL_SOCKET 65535 and 1), so each platform's table is generated by a ruby
# running there and the interpreter picks one by sys_os (Mere v0.1.642):
#
#   . ./tools/ref_ruby.sh && MKCONSTANTS=<ruby>/ext/socket/mkconstants.rb ruby tools/gen_socket_consts.rb   # darwin
#   docker run --rm -v $PWD/tools:/t -v <ruby>/ext/socket:/mk -e MKCONSTANTS=/mk/mkconstants.rb \
#     ruby:3.4-slim ruby /t/gen_socket_consts.rb                      # linux
# (a ruby's version does not change these numbers; the C library's headers do)
#
# ⚠ THE ORDER IS ext/socket/mkconstants.rb'S, not #constants'. A name that
# shares its value with another (AF_UNIX and AF_LOCAL are both 1) is answered
# by the reverse lookup as the FIRST of them there (constdefs.c builds its
# int-to-name tables by walking the list backwards and overwriting), and
# Socket::Constants#constants lists them in another order on Linux: RISC-V's
# `Addrinfo.unix("foo").marshal_dump` said AF_LOCAL where Linux CRuby says
# AF_UNIX (corpus/250, note 307). Pass the file as MKCONSTANTS=<path>.
require "socket"
rows = Socket::Constants.constants.filter_map do |c|
  v = Socket.const_get(c)
  v.is_a?(Integer) ? "#{c}=#{v}" : nil
end
if (mk = ENV["MKCONSTANTS"])
  order = {}
  File.foreach(mk) { |l| order[$1] ||= order.size if l =~ /\A([A-Z][A-Z0-9_]*)\t/ }
  rows = rows.each_with_index.sort_by { |r, i| [order.fetch(r.split("=")[0], order.size + i), i] }.map(&:first)
else
  warn "MKCONSTANTS is not set: the table is in #constants' order, which is not the reverse lookup's"
end
warn "#{rows.size} socket constants"
puts rows.join(" ")
